/* File: style.css */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  background-color: #121212;
}

.calculator {
  background-color: #1e1e1e;
  padding: 24px;
  border-radius: 16px;
  box-shadow: 0px 10px 30px rgba(0, 0, 0, 0.5);
  width: 320px;
}

.calculator-screen {
  width: 100%;
  height: 60px;
  background-color: #2a2a2a;
  border: none;
  border-radius: 8px;
  color: #ffffff;
  font-size: 2rem;
  text-align: right;
  padding: 0 15px;
  margin-bottom: 20px;
  outline: none;
}

.calculator-keys {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

button {
  height: 55px;
  background-color: #333333;
  border: none;
  border-radius: 10px;
  color: #ffffff;
  font-size: 1.2rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

button:hover {
  background-color: #444444;
}

button:active {
  transform: scale(0.95);
}

button.operator {
  background-color: #ff9500;
}

button.operator:hover {
  background-color: #e08300;
}

button.clear {
  background-color: #d9534f;
}

button.clear:hover {
  background-color: #c9302c;
}

button.equal-sign {
  background-color: #28a745;
  grid-row: span 2;
  height: 100%;
}

button.equal-sign:hover {
  background-color: #218838;
}

button.zero-btn {
  grid-column: span 2;
}
